begin;
create extension if not exists pgtap with schema extensions;
select extensions.plan(12);
select extensions.ok(to_regprocedure('public.initiate_sellertray_pos_bank_transfer(uuid,uuid,uuid,uuid)') is not null,'POS bank transfer initiation command exists');
select extensions.ok(to_regprocedure('public.finalize_sellertray_pos_confirmed_payment(uuid,uuid)') is not null,'confirmed POS payment finalizer exists');
select extensions.ok(not has_function_privilege('authenticated','public.initiate_sellertray_pos_bank_transfer(uuid,uuid,uuid,uuid)','EXECUTE') and has_function_privilege('service_role','public.initiate_sellertray_pos_bank_transfer(uuid,uuid,uuid,uuid)','EXECUTE'),'bank transfer initiation stays behind service boundary');
select extensions.ok(not has_function_privilege('authenticated','public.finalize_sellertray_pos_confirmed_payment(uuid,uuid)','EXECUTE') and has_function_privilege('service_role','public.finalize_sellertray_pos_confirmed_payment(uuid,uuid)','EXECUTE'),'POS finalization stays behind service boundary');
select extensions.ok(exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='initiate_sellertray_pos_bank_transfer' and lower(pg_get_functiondef(p.oid)) like '%pending_verification%' and lower(pg_get_functiondef(p.oid)) like '%paymentstatus%unpaid%'),'bank transfer begins pending and unpaid');
select extensions.ok(exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='initiate_sellertray_pos_bank_transfer' and lower(pg_get_functiondef(p.oid)) not like '%record_sellertray_inventory_movement%'),'pending bank transfer does not decrement inventory');
select extensions.ok(exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='initiate_sellertray_pos_bank_transfer' and lower(pg_get_functiondef(p.oid)) not like '%fulfillment_status=''collected''%'),'pending bank transfer does not fulfil the sale');
select extensions.ok(exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='finalize_sellertray_pos_confirmed_payment' and lower(pg_get_functiondef(p.oid)) like '%status<>''confirmed''%' and lower(pg_get_functiondef(p.oid)) like '%record_sellertray_inventory_movement%'),'stock movement requires confirmed payment');
select extensions.ok(exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='finalize_sellertray_pos_confirmed_payment' and lower(pg_get_functiondef(p.oid)) like '%pg_advisory_xact_lock%' and lower(pg_get_functiondef(p.oid)) like '%insufficient stock%'),'settlement rechecks stock under advisory lock');
select extensions.ok(exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='confirm_sellertray_offline_payment' and lower(pg_get_functiondef(p.oid)) like '%orderdesk_subscription_can_write%' and lower(pg_get_functiondef(p.oid)) like '%sellertray_user_can_operate_branch%' and lower(pg_get_functiondef(p.oid)) like '%can_manage_payments%'),'manual confirmation preserves subscription, Branch and management authority');
select extensions.ok(exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='confirm_sellertray_offline_payment' and lower(pg_get_functiondef(p.oid)) like '%method_type=''bank_transfer''%' and lower(pg_get_functiondef(p.oid)) like '%finalize_sellertray_pos_confirmed_payment%'),'confirmed POS bank transfer invokes governed finalization');
select extensions.ok(exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='complete_sellertray_pos_sale' and lower(pg_get_functiondef(p.oid)) like '%bank_transfer%' and lower(pg_get_functiondef(p.oid)) like '%card_terminal%'),'existing unified immediate checkout remains available for cash/card terminal compatibility');
select * from extensions.finish();
rollback;